generated_pydough:
filtered_concerts = concerts.WHERE(
    (concerts.year == '2014') | (concerts.year == '2015')
).CALCULATE(
    group_id=1
)

total_concerts_2014_2015 = filtered_concerts.PARTITION(
    name="single_group", by=(group_id)
).CALCULATE(
    number_of_concerts=COUNT()
)

youngest_dog_weight = pet.WHERE(pettype == 'dog').CALCULATE(
    age_rank = RANKING(by=pet_age.ASC(), allow_ties=True)
).WHERE(age_rank == 1).CALCULATE(
    youngest_dog_weight_value = weight
)

# Filter the 'Pets' collection to include only records where PetType is 'dog'.
# Then, use TOP_K to find the single dog with the lowest pet_age (ascending order).
# Finally, select the 'weight' attribute of this youngest dog.
result = Pets.WHERE(
    PetType == 'dog'
).TOP_K(
    1, by=pet_age.ASC()
).CALCULATE(
    weight_of_youngest_dog=weight
)

result = stadiums.CALCULATE(
    stadium_name=name,
    capacity=capacity,
    num_relevant_concerts=COUNT(self.concerts.WHERE(TO_INT(self.concerts.year) >= 2014))
).WHERE(
    num_relevant_concerts > 0
).TOP_K(
    1, by=num_relevant_concerts.DESC()
).CALCULATE(
    stadium_name=stadium_name,
    capacity=capacity
)

