# First, filter the apartment bookings by status and extract the room count
provisional_apartment_room_counts = apartment_booking.WHERE(
    booking_status_code == "Provisional"
).CALCULATE(
    room_count_value = apartment.room_count
)

# Then, calculate the global average of these room counts using RELAVG
average_room_count_provisional = provisional_apartment_room_counts.CALCULATE(
    average_room_count = RELAVG(room_count_value)
)

# Step 1: Get the IDs of apartments that have a "Gym" facility
gym_related_apt_ids = apartment_facility.WHERE(
    facility_code == "Gym"
).CALCULATE(
    related_apartment_id=apartment.apt_id
)

# Step 2: Sum the room_count for these identified apartments
summed_room_count = apartment.WHERE(
    ISIN(apt_id, gym_related_apt_ids.related_apartment_id)
).CALCULATE(
    total_gym_rooms=SUM(INTEGER(room_count))
)

apartment_rooms_data = Apartments.CALCULATE(
