    room_count_int=DEFAULT_TO(INT(room_count), 0)
)

result = apartment_rooms_data.PARTITION(
    name="apt_types_group",
    by=apt_type_code
).CALCULATE(
    apt_type_code=apt_type_code,
    average_room_count=AVG(apartment_rooms_data.room_count_int)
).TOP_K(3, by=average_room_count.DESC()).CALCULATE(
    apt_type_code=apt_type_code
)

