# Step 1: Find the minimum salary among instructors in the Biology department.
min_biology_salary = instructors.WHERE(dept_name == 'Biology').CALCULATE(
    min_salary_val=MIN(salary)
).SINGULAR().min_salary_val

# Step 2: Get the names of instructors who earn more than this minimum.
result = instructors.WHERE(
    salary > min_biology_salary
).CALCULATE(
    instructor_name=name
)

