# 1. Calculate the overall maximum movie year at the GRAPH level.
max_movie_year_data = GRAPH.CALCULATE(
    max_movie_year_val=MAX(Movie.year)
)

# 2. Filter ratings to include only those for movies from the max_movie_year.
# 3. Group by the movie year and then calculate the maximum stars.
result = GRAPH.Rating.WHERE(
    movie.year == max_movie_year_data.SINGULAR().max_movie_year_val
).GROUP_BY(
    most_recent_movie_year=movie.year # Group by the year
).CALCULATE(
    max_stars_for_recent_movie=MAX(stars)
)

lowest_oppose_candidates = candidates.CALCULATE(
    candidate_sex=person.sex,
    candidate_name=person.name,
    candidate_oppose_rate=candidates.oppose_rate
).PARTITION(
    name="sex_groups",
    by=candidate_sex
).WHERE(
    RANKING(by=candidate_oppose_rate.ASC(), per="sex_groups", allow_ties=True) == 1
).CALCULATE(
    candidate_name=candidate_name,
    candidate_oppose_rate=candidate_oppose_rate
)

