customers_with_both_products = customer.CALCULATE(
    # Count distinct product details (Latte or Americano) for each customer
    # This will be 2 if both were ordered
    distinct_products_count = NDISTINCT(
        customer_order.order_item.product.WHERE(
            (product_details == 'Latte') | (product_details == 'Americano')
        ).product_details
    )
).WHERE(
    # Filter for customers who have exactly 2 distinct products (meaning they ordered both Latte and Americano)
    distinct_products_count == 2
).CALCULATE(
    # Select only the customer name
    customer_name = customer_name
)

